const payload = $input.first().json;
const properties = payload.body?.data?.properties ?? {};

const getTitle = (property) =>
  property?.title?.map(item => item?.plain_text ?? '').join('').trim() ?? '';

const getRichText = (property) =>
  property?.rich_text?.map(item => item?.plain_text ?? '').join('').trim() ?? '';

const issue = getTitle(properties['Обращение']) || 'Обращение';
const status = properties['Статус']?.status?.name ?? '';
const answer = getRichText(properties['Ответ']);
const chatId = getRichText(properties['Telegram chat ID']);

const statusLine = {
  'В работе': 'Принято в работу 🛠️',
  'Решено': 'Решено ✅',
  'Не по адресу': 'Не по адресу ↪️',
}[status];

if (!statusLine || !chatId) {
  return [];
}

const parts = [statusLine, issue];

if ((status === 'Решено' || status === 'Не по адресу') && answer) {
  parts.push(answer);
}

return [{
  json: {
    chatId,
    text: parts.join('\n\n'),
    status,
    issue,
    hasAnswer: Boolean(answer),
    notionPageId: payload.body?.data?.id ?? '',
    notionEventId: payload.body?.source?.event_id ?? ''
  }
}];
